  2	
  3	import hotel.documents.ReservationReceipt;
  4	import hotel.messages.EmailSender;
  5	import hotel.notifications.ReservationNotifier;
  6	import hotel.rooms.Room;
  7	import hotel.rooms.Rooms;
  8	import java.math.BigDecimal;
  9	import java.util.ArrayList;
 10	import java.util.List;
 11	
 12	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 13	public final class ReservationService {
 14	
 15	    static final String HOTEL_NAME = "Pousada Maré Alta";
 16	
 17	    private final Rooms rooms;
 18	    private final ReservationStore store;
 19	    private final PriceCalculator priceCalculator;
 20	    private final EmailSender emailSender;
 21	    private final List<ReservationNotifier> notifiers;
 22	
 23	    public ReservationService(
 24	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 25	        this.rooms = rooms;
 26	        this.store = store;
 27	        this.priceCalculator = priceCalculator;
 28	        this.emailSender = emailSender;
 29	        this.notifiers = new ArrayList<>();
 30	    }
 31	
 32	    public void addNotifier(ReservationNotifier notifier) {
 33	        notifiers.add(notifier);
 34	    }
 35	
 36	    public synchronized Reservation create(NewReservation request) {
 37	        if (!request.checkOut().isAfter(request.checkIn())) {
 38	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 39	        }
 40	        if (request.guests() < 1) {
 41	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 42	        }
 43	        Room room = rooms.find(request.roomNumber())
 44	                .orElseThrow(() -> new HotelException(
 45	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 46	        if (request.guests() > room.capacity()) {
 47	            throw new HotelException(
 48	                    ErrorCode.CAPACITY_EXCEEDED,
 49	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 50	        }
 51	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 52	            throw new HotelException(
 53	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 54	        }
 55	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 56	        return store.add(request, price);
 57	    }
 58	
 59	    public Reservation find(long reservationId) {
 60	        return store.find(reservationId)
 61	                .orElseThrow(() -> new HotelException(
 62	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 63	    }
 64	
 65	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 66	    public synchronized Reservation confirm(long reservationId) {
 67	        Reservation reservation = find(reservationId);
 68	        if (reservation.status() != ReservationStatus.PENDING) {
 69	            throw notAllowed(reservation, "confirm");
 70	        }
 71	        reservation.confirmPayment();
 72	        store.update(reservation);
 73	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 74	        Room room = roomOf(reservation);
 75	        emailSender.send(
 76	                reservation.guest().email(),
 77	                "Reserva confirmada - " + HOTEL_NAME,
 78	                confirmationEmailBody(reservation, receipt));
 79	        for (ReservationNotifier notifier : notifiers) {
 80	            notifier.onConfirmed(reservation, room);
 81	        }
 82	        return reservation;
 83	    }
 84	
 85	    /**
 86	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 87	     * reservation was never paid, so nothing comes back).
 88	     */
 89	    public synchronized Reservation cancel(long reservationId) {
 90	        Reservation reservation = find(reservationId);
 91	        if (reservation.status() != ReservationStatus.PENDING
 92	                && reservation.status() != ReservationStatus.CONFIRMED) {
 93	            throw notAllowed(reservation, "cancel");
 94	        }
 95	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
 96	        BigDecimal refund = switch (reservation.ratePlan()) {
 97	            case STANDARD -> reservation.amountPaid();
 98	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
 99	        };
100	        reservation.cancel(refund);
101	        store.update(reservation);
102	        if (wasConfirmed) {
103	            Room room = roomOf(reservation);
104	            for (ReservationNotifier notifier : notifiers) {
105	                notifier.onCancelled(reservation, room);
106	            }
107	        }
108	        return reservation;
109	    }
110	
111	    public synchronized Reservation checkIn(long reservationId) {
112	        Reservation reservation = find(reservationId);
113	        if (reservation.status() != ReservationStatus.CONFIRMED) {
114	            throw notAllowed(reservation, "check in");
115	        }
116	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
117	        store.update(reservation);
118	        return reservation;
119	    }
120	
121	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
122	    public synchronized ReservationReceipt checkOut(long reservationId) {
123	        Reservation reservation = find(reservationId);
124	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
125	            throw notAllowed(reservation, "check out");
126	        }
127	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
128	        store.update(reservation);
129	        return new ReservationReceipt(reservation, roomOf(reservation));
130	    }
131	
132	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
133	    public ReservationReceipt receiptCopy(long reservationId) {
134	        Reservation reservation = find(reservationId);
135	        if (!reservation.isPaid()) {
136	            throw notAllowed(reservation, "issue a receipt for");
137	        }
138	        return new ReservationReceipt(reservation, roomOf(reservation));
139	    }
140	
141	    private Room roomOf(Reservation reservation) {
142	        return rooms.find(reservation.roomNumber()).orElseThrow();
143	    }
144	
145	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
146	        return "Olá, " + reservation.guest().name() + "!\n\n"
147	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
148	                + receipt.text() + "\n"
149	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
150	                + "Até breve!\n";
151	    }
152	
153	    private static HotelException notAllowed(Reservation reservation, String operation) {
154	        return new HotelException(
155	                ErrorCode.OPERATION_NOT_ALLOWED,
156	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
157	    }
158	}
