122	    public synchronized ReservationReceipt checkOut(long reservationId) {
123	        Reservation reservation = find(reservationId);
124	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
125	            throw notAllowed(reservation, "check out");
126	        }
